mapper.select:
SELECT review_id, acm_name, content, created_at, rating FROM ( SELECT r.review_id review_id, a.acm_name acm_name, r.content content, r.created_at created_at, r.rating rating, ROW_NUMBER() OVER (ORDER BY r.created_at DESC) AS rnum FROM accommodation a JOIN review r ON a.acm_id = r.acm_id WHERE r.user_id = #{user_id}
AND INSTR(r.content, #{keyWord}) > 0
) WHERE rnum BETWEEN #{startNum} AND #{endNum}

SELECT COUNT(*) AS totalCount
FROM review
WHERE user_id = #{user_id}

SELECT img_name
FROM review_img
WHERE review_id = #{review_id}

mapper.insert:
